use vstd::prelude::*;

verus! {

// Specification function: checks if string contains 'z' or 'Z'
spec fn has_z(s: Seq<char>) -> bool {
    exists|i: int| 0 <= i < s.len() && (s[i] == 'z' || s[i] == 'Z')
}

fn contains_z(s: &str) -> (result: bool)
    ensures
        result == has_z(s@),
{
    let mut i: usize = 0;
    let chars = s@;
    
    while i < s.unicode_len()
        invariant
            i <= s.unicode_len(),
            chars == s@,
            // If we haven't found 'z' or 'Z' yet, none exist in [0..i)
            forall|j: int| 0 <= j < i ==> !(chars[j] == 'z' || chars[j] == 'Z'),
        decreases s.unicode_len() - i,
    {
        let c = s.get_char(i);
        
        if c == 'z' || c == 'Z' {
            assert(chars[i as int] == c);
            assert(has_z(s@));
            return true;
        }
        
        i = i + 1;
    }
    
    // Prove that if we've checked all positions and found nothing, 
    // then no 'z' or 'Z' exists
    assert(forall|j: int| 0 <= j < chars.len() ==> 
        !(chars[j] == 'z' || chars[j] == 'Z'));
    assert(!has_z(s@));
    
    false
}

}

